def prime_fib(n: int) -> int:
    import math

    if n < 2:
        return 2
    if n == 2:
        return 3
    if n % 2 == 0:
        return 5

    # Generate Fibonacci numbers up to n
    fibs = [0, 1, 2]
    for _ in range(3, n + 1):
        fibs.append(fibs[-1] + fibs[-2])

    # Check primality for each Fibonacci number
    for f in fibs:
        if f > n:
            break
        if f > 1 and f < 2:
            continue
        if f % 2 == 0:
            continue
        if f in [2, 3]:
            continue

        # Check primality using trial division up to sqrt(f)
        if f < 2:
            continue
        for d in range(2, int(math.isqrt(f)) + 1):
            if f % d == 0:
                break
        else:
            return f

    return 0  # Should not be reached

